// Generator of tests/vendor/p4_v1_golden.inc (NOT built by CMake; run once, output reviewed and
// committed). It evaluates the ORIGINAL PoseEstimationAnalytic::Evaluate, i.e. the vendored
// bundle-residual-analytic.cc without v1-pose-estimation-exact-limit.patch, and prints the inputs and
// the 14 output doubles (2 residuals, 12 Jacobian entries) as hex bits, so that sr_p4_v1_test can
// check "switch off = original, bit for bit" without a copy of the original code.
//
// Build (from the build tree of the engine, all libraries already built there), the unpatched
// translation unit is compiled from the patched file with the patch reversed:
//   patch -R -p1 -d <scratch>/a < third_party/xr_source/patches/v1-pose-estimation-exact-limit.patch
//   g++ -std=c++17 -O2 -ffp-contract=off -fno-fast-math -march=x86-64 -DJAVASCRIPT -DC8_NO_EXCEPT \
//       -I<xr_shim> -I<xr_source> -I<libcxx_compat/include> -I<eigen> -I<ceres include> \
//       p4_v1_golden_gen.cc <scratch>/reality/engine/geometry/bundle-residual-analytic.cc \
//       <libs of the build tree: sr_vendor_geometry sr_vendor_features sr_vendor_c8 ceres ...>
// Input values are printed, so the committed golden does not depend on the libm that built it.

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <vector>

#include "p4_v1_scene.h"
#include "reality/engine/geometry/bundle-residual-analytic.h"
#include "reality/engine/geometry/observed-point.h"

namespace {

uint64_t Bits(double d) {
  uint64_t u;
  std::memcpy(&u, &d, sizeof(u));
  return u;
}
uint32_t Bits(float f) {
  uint32_t u;
  std::memcpy(&u, &f, sizeof(u));
  return u;
}

struct Row {
  const char* tag;
  p4v1::Pose pose;
  double X[3];
  float u, v, w;
};

void Emit(const Row& row) {
  c8::ObservedPoint pt;
  pt.position = c8::HPoint2(row.u, row.v);
  pt.scale = 0;
  pt.descriptorDist = 0.0f;
  pt.weight = row.w;
  c8::PoseEstimationAnalytic f(row.X[0], row.X[1], row.X[2], pt, 1.0);
  double params[6] = {row.pose.r[0], row.pose.r[1], row.pose.r[2], row.pose.t[0], row.pose.t[1], row.pose.t[2]};
  const double* pp[1] = {params};
  double res[2];
  double jac[12];
  double* jp[1] = {jac};
  f.Evaluate(pp, res, jp);
  std::printf("    {\"%s\", {", row.tag);
  for (int i = 0; i < 6; ++i) std::printf("0x%016llxull%s", (unsigned long long)Bits(params[i]), i < 5 ? ", " : "");
  std::printf("}, {");
  for (int i = 0; i < 3; ++i) std::printf("0x%016llxull%s", (unsigned long long)Bits(row.X[i]), i < 2 ? ", " : "");
  std::printf("}, 0x%08xu, 0x%08xu, 0x%08xu,\n     {", Bits(row.u), Bits(row.v), Bits(row.w));
  for (int i = 0; i < 2; ++i) std::printf("0x%016llxull, ", (unsigned long long)Bits(res[i]));
  for (int i = 0; i < 12; ++i) std::printf("0x%016llxull%s", (unsigned long long)Bits(jac[i]), i < 11 ? ", " : "");
  std::printf("}},\n");
}

}  // namespace

int main() {
  const p4v1::Pose poses[3] = {{{0.31, -0.42, 0.27}, {0.12, -0.07, 0.35}},   // general branch
                         {{1.4, -1.1, 1.5}, {-0.2, 0.1, 0.4}},         // general branch, large angle
                         {{3e-4, -2e-4, 1e-4}, {0.05, 0.02, 0.1}}};    // small rotation branch
  const char* names[3] = {"A", "B", "S"};
  const double sigmas[] = {0.0,   1e-13, -1e-13, 7.0e-11, -7.0e-11, 7.2e-11,
                           -7.2e-11, 1e-9,   -1e-9,   1e-3,    -1e-3};
  std::printf("// Generated by p4_v1_golden_gen.cc from the unpatched bundle-residual-analytic.cc.\n");
  static char tag[96];
  for (int pi = 0; pi < 3; ++pi) {
    for (const double depth : {2.5, -2.5}) {
      if (pi != 0 && depth < 0) continue;  // behind the camera only on pose A
      for (const float w : {1.0f, 0.5f}) {
        if (pi != 0 && w != 1.0f) continue;
        for (const double sigma : sigmas) {
          Row row;
          std::snprintf(tag, sizeof(tag), "%s depth%+.1f w%.1f sigma_u%+.1e", names[pi], depth, (double)w, sigma);
          row.tag = tag;
          row.pose = poses[pi];
          p4v1::WorldPointAtError(row.pose, depth, sigma, 0.01, row.X);
          row.u = 0.25f;
          row.v = 0.125f;
          row.w = w;
          Emit(row);
        }
      }
    }
    for (const double sigma : {0.0, 3e-11, -3e-11}) {  // both components degenerate
      Row row;
      std::snprintf(tag, sizeof(tag), "%s both sigma%+.1e", names[pi], sigma);
      row.tag = tag;
      row.pose = poses[pi];
      p4v1::WorldPointAtError(row.pose, 2.5, sigma, -sigma, row.X);
      row.u = 0.25f;
      row.v = 0.125f;
      row.w = 1.0f;
      Emit(row);
    }
  }
  return 0;
}
